 [ObservableProperty] private Nav? selectedNav;[ObservableProperty] private IList rows=new List<object>();[ObservableProperty] private object? selectedRow;[ObservableProperty] private List<ProductRow> searchResults=[];[ObservableProperty] private ProductRow? selectedProduct;[ObservableProperty] private CartRow? selectedCart;
 [ObservableProperty] private string search="";[ObservableProperty] private string status="Ready / جاهز";[ObservableProperty] private bool busy;[ObservableProperty] private string discount="0";[ObservableProperty] private string cash="0";[ObservableProperty] private string card="0";[ObservableProperty] private string customerId="";[ObservableProperty] private string notes="";
