 [ObservableProperty] private DateTime fromDate=DateTime.Today;[ObservableProperty] private DateTime throughDate=DateTime.Today;
 public bool Ready=>!Busy;public bool IsPos=>SelectedNav?.Key=="pos";public bool IsDashboard=>SelectedNav?.Key=="dashboard";public bool IsTable=>!IsPos&&!IsDashboard;public bool ShowDates=>SelectedNav?.Key is "dashboard" or "reports" or "sales";
 public MainViewModel(Session session,SecurityService security,PosService pos,ExcelService excel,BackupService backup,IDbFactory factory,DialogService dialogs,PrintService printing,ILogger<MainViewModel> logger){Session=session;this.security=security;this.pos=pos;this.excel=excel;this.backup=backup;this.factory=factory;this.dialogs=dialogs;this.printing=printing;this.logger=logger;Cart.CollectionChanged+=(_,_)=>Recalculate();LoadPreferences();SelectedNav=Navigation.FirstOrDefault();}
 private bool Can(string permission)=>security.Can(Session,permission);
 private void LoadPreferences(){settings=pos.Settings(Session);L=new Texts(settings.GetValueOrDefault("Language")=="ar");OnPropertyChanged(nameof(L));OnPropertyChanged(nameof(StoreName));OnPropertyChanged(nameof(Currency));OnPropertyChanged(nameof(Direction));ApplyTheme(settings.GetValueOrDefault("Theme")=="dark");Navigation.Clear();
  (string key,string name,string permission)[] navs=[("dashboard","Dashboard","Reports.ViewOwn"),("pos","Point of Sale","Sales.Create"),("products","Products","Products.View"),("categories","Categories","Products.View"),("inventory","Inventory","Inventory.View"),("purchases","Purchases","Purchases.Manage"),("suppliers","Suppliers","Suppliers.Manage"),("customers","Customers","Customers.View"),("sales","Sales History","Sales.ViewOwn"),("expenses","Expenses","Expenses.View"),("reports","Reports","Reports.ViewOwn"),("shifts","Shifts","Shifts.Own"),("users","Employees","Users.Manage"),("permissions","Roles & Permissions","Permissions.Manage"),("excel","Excel Import/Export","Excel.Import"),("backup","Backup & Restore","Backup.Create"),("settings","Settings","Settings.Manage"),("audit","Audit Logs","AuditLogs.View")];foreach(var n in navs)if(Can(n.permission)||n.key=="excel"&&Can("Excel.Export"))Navigation.Add(new Nav(n.key,L[n.name],n.permission));}
 private static void ApplyTheme(bool dark){var resources=System.Windows.Application.Current.Resources;foreach(var (key,color) in new Dictionary<string,string>{{"BackgroundBrush",dark?"#121B2A":"#F3F5F9"},{"SurfaceBrush",dark?"#1B283D":"#FFFFFF"},{"TextBrush",dark?"#F1F5FC":"#162238"},{"MutedBrush",dark?"#ADBCD3":"#586780"},{"BorderBrush",dark?"#34445E":"#DCE2ED"}})resources[key]=new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(color));}
 partial void OnSelectedNavChanged(Nav? value){OnPropertyChanged(nameof(IsPos));OnPropertyChanged(nameof(IsDashboard));OnPropertyChanged(nameof(IsTable));OnPropertyChanged(nameof(ShowDates));SelectedRow=null;shownSaleId=null;_ = RefreshAsync();}
